import{_ as t}from"./chunks/console-qa-feedback.De5dX-GL.js";import{_ as a,o as r,c as o,a3 as s}from"./chunks/framework.DhF4LrUq.js";const f=JSON.parse('{"title":"QA Engineer quickstart","description":"Quickstart for QA Engineers — the QA approval step, tester groups, feedback triage, crash-free gates, and the device fleet picture.","frontmatter":{"description":"Quickstart for QA Engineers — the QA approval step, tester groups, feedback triage, crash-free gates, and the device fleet picture."},"headers":[],"relativePath":"roles/qa-engineer.md","filePath":"roles/qa-engineer.md"}'),i={name:"roles/qa-engineer.md"};function n(h,e,l,p,c,d){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="qa-engineer-quickstart" tabindex="-1">QA Engineer quickstart <a class="header-anchor" href="#qa-engineer-quickstart" aria-label="Permalink to &quot;QA Engineer quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You are quality&#39;s working surface. Your system role is <strong><code>QA_ENGINEER</code></strong>, and you live in the Console (with the Tester Portal your testers see, from the other side). Two things wait on you in every release: the <strong>QA approval step</strong> of the chain, and the feedback queue — the reports your testers file, which you triage, and whose open critical bugs can block a promotion outright. You also own tester groups, the rings of testers releases target. If you hold other roles too, work one track per session — the <a href="/shipperdog/snapshot/roles/">other role guides</a> cover the rest.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Sign the QA approval</strong> — the QA step of each release&#39;s approval chain is yours to approve or reject.</li><li><strong>Manage tester groups</strong> — create and shape the groups (per tenant) that releases target: Internal QA, UAT, Pilot, your own.</li><li><strong>Triage feedback</strong> — read every report on releases you can see, set severity, assign the member who works it, and move it through its lifecycle. Reports testers mark as security issues are not yours alone — see the <a href="/shipperdog/snapshot/roles/security-reviewer">Security Reviewer</a> track.</li><li><strong>Watch the quality numbers</strong> — read the release analytics your evidence feeds: crash-free sessions, ANR and uninstall rates, install success, tester engagement. The quality gates turn those numbers into promotion decisions; you read the gate definitions they answer to.</li><li><strong>See everything, change the pipeline nowhere</strong> — read-only visibility into environments, workflows, gates, rings, and policies. You judge the pipeline; the governance roles tune it.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Sign in and read the dashboard.</strong> Your pending-actions panel leads with QA approvals waiting on your signature.</p></li><li><p><strong>Open the release and sign the QA step.</strong> On the release dashboard&#39;s <strong>Approvals</strong> panel, find the QA step in the live round and approve or reject it. While you are there, check the <strong>Quality Gates</strong> panel — the crash-free and coverage gates read the same telemetry your triage works.</p></li><li><p><strong>Work the feedback queue.</strong> The release dashboard&#39;s feedback section is the triage surface: every report the release&#39;s testers filed, with the context the platform attached (application, version, build, device, OS). Set severity, assign an owner, move it through its lifecycle — an open critical bug is a promotion blocker, so severity is a release decision, not bookkeeping.</p><p><img src="'+t+'" alt="Feedback triage on the release dashboard"></p></li><li><p><strong>Shape a tester group.</strong> Groups are tenant-scoped and every tenant starts with defaults (Internal QA, Tenant QA, UAT, Pilot, Executive Beta, External Beta). Rename, regroup, and populate them so the next release targets exactly the roster you want. (Group management is an API operation today; the console surface lands with the console how-tos — <a href="/shipperdog/snapshot/how-to/console/feedback-triage">feedback triage</a>.)</p></li><li><p><strong>See what your testers see.</strong> Walk the <a href="/shipperdog/snapshot/get-started/five-minute-install">five-minute install</a> once, as a tester would — every rough edge you find there is a bug in the promise your queue will hear about.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/feedback-analytics">feedback analytics</a> — how reports become metrics, gates, and promotion decisions</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/approvals-gates">approvals and gates</a> for the chain you sign and the gates you feed</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/artifact-pipeline">the artifact pipeline</a> to know what a READY build has already survived</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/console/feedback-triage">feedback triage</a>, <a href="/shipperdog/snapshot/how-to/console/quality-gates">quality gates</a></li><li>[ ] Point your testers at the <a href="/shipperdog/snapshot/roles/tester">Tester quickstart</a></li></ul>',11)])])}const y=a(i,[["render",n]]);export{f as __pageData,y as default};
